D.subPaths.forEach(s=>{
 if(s.id==='STAR_ARCHER'){s.element='ASTRAL';s.elementProfile={mode:'INTRINSIC_WEIGHTED',primary:'ASTRAL',weights:{ASTRAL:.55,WIND:.45}};}
 else if(s.id==='SHADOW_ARCHER'){s.element='YIN_SHADOW';s.elementProfile={mode:'INTRINSIC_WEIGHTED',primary:'YIN_SHADOW',weights:{YIN_SHADOW:.6,WIND:.4}};}
 else if(s.id==='STAFF_GUARD'){s.element='EARTH_METAL';s.elementProfile={mode:'INTRINSIC_SINGLE',primary:'EARTH_METAL',weights:{EARTH_METAL:1}};}
});
D.items.forEach(it=>{
 const el=it.tier===1?'EARTH_METAL':it.tier===3?'ASTRAL':'FIRE';
 it.element=el;
 it.elementProfile=it.tier===5?{mode:'INTRINSIC_WEIGHTED',primary:'FIRE',weights:{FIRE:.55,EARTH_METAL:.45}}:it.tier===3?{mode:'INTRINSIC_WEIGHTED',primary:'ASTRAL',weights:{ASTRAL:.55,EARTH_METAL:.45}}:{mode:'INTRINSIC_SINGLE',primary:'EARTH_METAL',weights:{EARTH_METAL:1}};
});
D.recipes.forEach(r=>{
 const it=D.items.find(i=>i.id===r.outItemId);
 if(it){r.element=it.element;r.elementProfile=it.elementProfile;}
});
[...JD.TECH.techniques,...JD.TECH.mantras].forEach(t=>{
 if(PASSIVE_EL_MAP[t.id]){
  const spec=PASSIVE_EL_MAP[t.id];
  t.element=spec.el;
  const ks=Object.keys(spec.w);
  t.elementProfile=ks.length===0?{mode:'EXPLICIT_NON_ELEMENTAL',primary:'NEUTRAL',weights:{}}:ks.length===1?{mode:spec.el==='ASTRAL'||spec.el==='BLOOD_DEMON'?'SPECIAL_ELEMENT':'INTRINSIC_SINGLE',primary:spec.el,weights:spec.w}:{mode:'INTRINSIC_WEIGHTED',primary:spec.el,weights:spec.w};
  if(spec.comp){t.compositeElement=spec.comp;t.elementProfile.compositeTag=spec.comp;}
 } else if(!t.elementProfile){
  const AL={WATER:'WATER_ICE',ICE:'WATER_ICE',WOOD:'WOOD_LIFE',METAL:'EARTH_METAL',EARTH:'EARTH_METAL',YIN:'YIN_SHADOW',YANG:'LIGHT_YANG',LIGHT:'LIGHT_YANG',BLOOD:'BLOOD_DEMON'};const el=AL[t.element]||t.element||'NEUTRAL';
  t.element=el;
  t.elementProfile=el==='NEUTRAL'?{mode:'EXPLICIT_NON_ELEMENTAL',primary:'NEUTRAL',weights:{}}:el==='ASTRAL'||el==='BLOOD_DEMON'?{mode:'SPECIAL_ELEMENT',primary:el,weights:{[el]:1}}:{mode:'INTRINSIC_SINGLE',primary:el,weights:{[el]:1}};
 }
});
D.SYNERGIES.forEach(syn=>{
 const refTech=[...JD.TECH.techniques,...JD.TECH.mantras].find(x=>x.id===syn.techId);
 syn.element=refTech&&refTech.element||'NEUTRAL';
 syn.elementProfile=refTech&&refTech.elementProfile||{mode:'EXPLICIT_NON_ELEMENTAL',primary:'NEUTRAL',weights:{}};
});
