// 1) Subpaths into JD.CULT.paths & JD.MARTIAL.subPaths
EXP_V204.newSubPaths.forEach(s => {
  if (!D.subPaths.some(x => x.id === s.id)) D.subPaths.push(s);
  const p = JD.CULT.paths[s.path];
  if (p && !p.subPaths.some(x => x.id === s.id)) p.subPaths.push(s);
});

// 2) Subpath stats & preferences into JD.EXPANSION and JD.MARTIAL
JD.EXPANSION.subStats = Object.assign(JD.EXPANSION.subStats || {}, EXP_V204.allSubStats);
D.subStats = Object.assign(D.subStats || {}, EXP_V204.allSubStats);
JD.EXPANSION.subPreferences = Object.assign(JD.EXPANSION.subPreferences || {}, EXP_V204.allSubPrefs);
D.subPreferences = Object.assign(D.subPreferences || {}, EXP_V204.allSubPrefs);

// 3) 9-Realm progression tracks into JD.EXPANSION.progressionMapping
if (Array.isArray(JD.EXPANSION.progressionMapping)) {
  EXP_V204.newTracks.forEach(tr => {
    const sp = tr.subPath || tr.subPathId; tr.subPath = sp; if (!JD.EXPANSION.progressionMapping.some(x => (x.subPath || x.subPathId) === sp)) {
      JD.EXPANSION.progressionMapping.push(tr);
    }
  });
}

// 4) Innate Subpath Techniques into D.innateTechniques & JD.TECH.techniques
D.innateTechniques = D.innateTechniques || [];
EXP_V204.newInnateTechniques.forEach(t => {
  if (!D.innateTechniques.some(x => x.id === t.id)) D.innateTechniques.push(t);
  if (!JD.TECH.techniques.some(x => x.id === t.id)) JD.TECH.techniques.push(t);
});

// 5) Learnable Techniques & Mantras into JD.TECH.techniques, JD.TECH.mantras & D.techniques
EXP_V204.newTechniques.forEach(t => {
  if (!D.techniques.some(x => x.id === t.id)) D.techniques.push(t);
  if (!JD.TECH.techniques.some(x => x.id === t.id)) {
    if (t.tier === 1 && !t.sub && (t.path === 'XIAN' || t.path === 'ANY')) {
      const baseIdx = JD.TECH.techniques.findIndex(x => x.id === 'MP_BASE_HEART_SOUL');
      if (baseIdx >= 0) JD.TECH.techniques.splice(baseIdx + 1, 0, t);
      else JD.TECH.techniques.push(t);
    } else {
      JD.TECH.techniques.push(t);
    }
  }
});
EXP_V204.newMantras.forEach(m => {
  if (!JD.TECH.mantras.some(x => x.id === m.id)) JD.TECH.mantras.push(m);
});

// 6) Synergies into D.SYNERGIES
D.SYNERGIES = D.SYNERGIES || [];
EXP_V204.newSynergies.forEach(syn => {
  if (!D.SYNERGIES.some(x => x.id === syn.id)) D.SYNERGIES.push(syn);
});

// 7) Equipment Items & Recipes into JD.ITEMS.items, JD.ITEMS.recipes, D.expansionItems, D.expansionRecipes
D.expansionItems = EXP_V204.newItems;
D.expansionRecipes = EXP_V204.newRecipes;
EXP_V204.newItems.forEach(it => {
  if (!JD.ITEMS.items.some(x => x.id === it.id)) JD.ITEMS.items.push(it);
});
EXP_V204.newRecipes.forEach(r => {
  if (!JD.ITEMS.recipes.some(x => x.id === r.id)) JD.ITEMS.recipes.push(r);
});

// Ensure all existing neutral techniques/mantras also carry elementalRole: 'EXPLICIT_NON_ELEMENTAL'
[...JD.TECH.techniques, ...JD.TECH.mantras].forEach(t => {
  if (t.elementalRole === 'EXPLICIT_NON_ELEMENTAL') {
    if (!t.elementProfile) t.elementProfile = { mode: 'EXPLICIT_NON_ELEMENTAL', primary: 'NEUTRAL', weights: {} };
    delete t.element;
  } else if (t.element === 'NEUTRAL' || (t.elementProfile && t.elementProfile.mode === 'EXPLICIT_NON_ELEMENTAL')) {
    t.elementalRole = 'EXPLICIT_NON_ELEMENTAL';
    t.elementProfile = { mode: 'EXPLICIT_NON_ELEMENTAL', primary: 'NEUTRAL', weights: {} };
  }
});

